const SESSION_KEY='qrk_local_auth_session_v1';
const PREVIEW_USERS_KEY='qrk_preview_auth_users_v1';
const syntheticEmail=username=>`${username.trim().toLowerCase()}@accounts.qrkmenu.invalid`;

export class QrkAuthService{
  constructor(config){this.config=config;this.session=this.readSession()}
  get backendEnabled(){return Boolean(this.config.supabaseUrl&&this.config.supabasePublishableKey)}
  get enabled(){return Boolean(this.session?.preview||(this.config.authEnabled&&(this.backendEnabled||this.config.environment==='preview')))}
  readSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
  saveSession(session){this.session=session;if(session)localStorage.setItem(SESSION_KEY,JSON.stringify(session));else localStorage.removeItem(SESSION_KEY)}
  headers(token=this.session?.access_token){return{'content-type':'application/json','apikey':this.config.supabasePublishableKey,...(token?{authorization:`Bearer ${token}`}:{})}}
  async request(path,{method='POST',body,token}={}){const response=await fetch(`${this.config.supabaseUrl}${path}`,{method,headers:this.headers(token),body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok)throw new Error('Sign-in failed. Check your username or email and password.');return response.status===204?null:response.json()}
  previewUsers(){try{return JSON.parse(localStorage.getItem(PREVIEW_USERS_KEY)||'[]')}catch{return[]}}
  savePreviewUsers(users){localStorage.setItem(PREVIEW_USERS_KEY,JSON.stringify(users))}
  generateTemporaryPassword(){const pick=chars=>chars[crypto.getRandomValues(new Uint32Array(1))[0]%chars.length],sets=['ABCDEFGHJKLMNPQRSTUVWXYZ','abcdefghijkmnopqrstuvwxyz','23456789','!@#$%'];let value=sets.map(pick).join('');const all=sets.join('');while(value.length<12)value+=pick(all);return [...value].sort(()=>crypto.getRandomValues(new Uint32Array(1))[0]/2**32-.5).join('')}
  createPreviewUser(account){const username=account.username.trim().toLowerCase(),users=this.previewUsers();if(users.some(user=>user.username===username))throw new Error('That username is already in use.');const temporaryPassword=this.generateTemporaryPassword();users.push({...account,username,password:temporaryPassword,mustChangePassword:true});this.savePreviewUsers(users);return{username,temporaryPassword}}
  async signInDevelopment(account){if(!['local','preview'].includes(this.config.environment))throw new Error('Preview shortcuts are not available in this environment.');const username=account.username.trim().toLowerCase(),password=this.config.developmentAccounts?.[username];if(password)return this.signIn(username,password);const users=this.previewUsers();let user=users.find(item=>item.username===username);if(!user){user={...account,username,password:'',mustChangePassword:false,isDevelopmentShortcut:true};users.push(user);this.savePreviewUsers(users)}this.saveSession({preview:true,username});return this.restore()}
  async signIn(identifier,password){const normalized=identifier.trim().toLowerCase(),preview=this.previewUsers().find(user=>(user.username===normalized||user.email?.toLowerCase()===normalized)&&user.password===password);if(preview){this.saveSession({preview:true,username:preview.username});return this.restore()}if(!this.backendEnabled)throw new Error('This preview account is not available on this device.');const email=identifier.includes('@')?normalized:syntheticEmail(identifier);const session=await this.request('/auth/v1/token?grant_type=password',{body:{email,password}});this.saveSession(session);return this.restore()}
  async restore(){if(!this.session)return null;if(this.session.preview){if(!['local','preview'].includes(this.config.environment)){this.saveSession(null);return null}const user=this.previewUsers().find(item=>item.username===this.session.username);if(!user){this.saveSession(null);return null}return{...user,password:undefined,userId:`preview:${user.username}`,isPreview:true}}if(Date.now()/1000>(this.session.expires_at||0)-60){try{this.saveSession(await this.request('/auth/v1/token?grant_type=refresh_token',{body:{refresh_token:this.session.refresh_token},token:null}))}catch{this.saveSession(null);return null}}try{const context=await this.request('/rest/v1/rpc/get_my_access_context',{body:{}});if(!context?.businessId)throw new Error();return{...context,mustChangePassword:Boolean(this.session.user?.user_metadata?.must_change_password)}}catch{this.saveSession(null);return null}}
  async updatePassword(password){if(this.session?.preview){const users=this.previewUsers(),user=users.find(item=>item.username===this.session.username);if(!user)throw new Error('Account not found.');user.password=password;user.mustChangePassword=false;this.savePreviewUsers(users);return this.restore()}await this.request('/auth/v1/user',{method:'PUT',body:{password,data:{must_change_password:false}}});if(this.session?.user?.user_metadata)this.session.user.user_metadata.must_change_password=false;this.saveSession(this.session);return this.restore()}
  async signOut(){try{if(this.session&&!this.session.preview)await this.request('/auth/v1/logout',{body:{}})}finally{this.saveSession(null)}}
  accessToken(){return this.session?.access_token||''}
}
